"""Source-check diagnosis outputs; preserve every original model generation."""
import hashlib,json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/s1_empty_diagnosis'
def read(p):return json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
base=ROOT/'exp/s1_empty_speech'/read(D/'speech-submission.json')['job'];cases=read(base/'cases.json');reviews=[]
for c in cases:
 f=base/c['id'];r=read(f/'run.json');asr=read(f/'asr.json')['text'];tag=c['id'][:3]
 if c['history_mode']=='none':score=None;reason='Question-only recognition control; meeting facts are unavailable, so this is not an accuracy case.'
 elif c['id']=='P01-native-original':score=None;reason='All 41 native speech fields are empty and independent ASR is empty; the quiet codec waveform remains pending listening, not a confirmed spoken answer.'
 elif r['status']=='failed':score=0;reason='The complete input was processed, but the model returned ordinary text outside the four-field format; the caller could not produce a spoken answer.'
 elif tag=='P01':score=0;reason=('The response misses the earlier shared-file statement and identified PowerPoint; empty-folder and moved-file claims are unsupported, and no lookup was performed.' if c['prompt_changed'] else 'It repeats missing-file language but does not recover C’s earlier file statement or the identified components-design PowerPoint.')
 elif tag=='P02':score=0;reason='The response leaves the word uncertain, contrary to the equally-plausible choose-one policy agreed in the source.'
 elif c['id']=='P03-repair-original':score=None;reason='Native speech text is empty, while ASR reports fragments and letter names; this needs listening rather than automatic acceptance as speech.'
 elif c['prompt_changed'] and c['request_level_adjusted']:score=0;reason='It avoids confirming readiness but misses the discussed mapping of speech commands to existing functions; the answer is incomplete.'
 else:score=0;reason='A greeting does not answer the implementation-status request.'
 review={'reviewer':'Codex source, raw-field and independent-ASR inspection; no human listening rating','score':score,'reason':reason,'audio_sha256':r['audio_sha256'],'question_id':c['question_id'],'raw_run_sha256':hashlib.sha256((f/'run.json').read_bytes()).hexdigest(),'independent_response_transcript':asr,'source_reference_sha256':hashlib.sha256((ROOT/'research/s1_meeting_pilot/references.json').read_bytes()).hexdigest()};save(f/'source-review.json',review);reviews.append({'id':c['id'],**review})
# Content-only controls are kept separate from native spoken-answer scoring.
oracle=read(ROOT/'exp/s1_oracle_diagnosis'/read(D/'oracle-submission.json')['job']/'summary.json')
for c in oracle['cases']:
 tag=c['id'][:3];mode=c['mode']
 if tag=='P02':score=int(mode!='audio');reason='Choose-one policy is correctly recovered.' if score else 'The answer adds leaving it uncertain, contrary to the source.'
 elif tag=='P01':score=0;reason='Missing the identified components-design PowerPoint and/or adding unsupported folder-status claims.'
 else:score=0;reason='Missing the speech-command-to-existing-function proposal or asserting unconfirmed non-readiness.'
 c['source_review']={'complete_answer_score':score,'reason':reason,'reviewer':'Codex source inspection; diagnostic text only, not spoken-answer accuracy'}
save(D/'oracle-audit.json',oracle)
text=read(ROOT/'exp/s1_empty_diagnosis'/read(D/'submission.json')['job']/'summary.json');gains={c['pilot_id']:round(20*math.log10(c['gain']),2) for c in text['cases'] if c['id'].endswith('request-only-rms_adjusted')}
audit={'status':'source_review_complete_protocol_unvalidated','summary_bullets':['The S1 model is DuplexOmni, with S2 disabled; Moshi and MiniCPM have not run in this pilot.','Empty fields, quiet-input sensitivity, response-format rejection and waiting for disabled S2 are separate observed failures.','Gain and prompt changes elicit speech, but their combined condition gives 0/3 complete source-supported spoken answers.'],
'findings':['The empty P01 control is generated by the S1 language model itself: 41 valid responses have empty speech text, before the speech backend runs.','Question level changes recognition: the quiet native-packet questions are missed or misheard, while louder versions recover more of the request; this does not by itself recover the meeting facts.','The folder request triggers [THINK] in native-packet mode, so S1 waits for the deliberately disabled S2; the acknowledgement is not a completed lookup.','The correct plain-text answer from the earlier A100 run was lost at the caller’s format check, not at the audio encoder; generic format instructions reduce that interface failure but do not guarantee correct content.','The combined direct-answer prompt and gain produce spoken answers on all three questions, but all three miss or contradict required facts; silence reduction is not an accuracy fix.','Question-only buffered controls can also be silent, so these failures cannot be attributed to long meeting history alone.','Supplying the exact question text fixes the ambiguity answer in one ordinary-text control, while a full transcript still leaves unsupported status claims; both audio understanding and grounding need qualification.'],
'counts':{'distinct_questions':3,'thinker_conditions':22,'speech_conditions':16,'oracle_text_conditions':9,'combined_repair_spoken_answers':3,'combined_repair_complete_answers':0},'gain_db':gains,'scope':'These are caller/behavior diagnostics on three existing questions, not results for the full105 benchmark. Oracle text outputs are not native S1 speech baseline results. No model weights or question texts were changed.','software_fixture':'Suffixed diagnostic IDs now use an explicit progress index; a CPU HTTP/output fixture passed before the corrected speech run.','speech_delivery_finding':'Some independent transcripts contain request-like words or differ from native tts; whether this reflects speech generation or ASR errors still needs listening, and printed tts alone does not certify the spoken answer.',
'remaining':['Keep output-format errors, native empty fields, S2-waiting and ASR uncertainty separate in evaluation records.','Qualify native packet input and buffered answer-text modes separately; neither is established as a reliable long-meeting spoken-answer baseline.','Use the same source-grounded scoring contract to qualify Moshi and MiniCPM before full-bank runs; further prompt selection belongs on separate development meetings.'],'speech_reviews':reviews,'oracle_summary':'P02 is correct with audio plus the written question and with transcript plus question; remaining controls are incomplete or unsupported under the same strict fact checklist.'}
save(D/'audit.json',audit);print(json.dumps({'combined_repair_complete_answers':0,'combined_repair_spoken_answers':3,'gains_db':gains,'source_checked_speech_conditions':len(reviews)}))
